-- Carga historica de notas a partir de Gestao de Faturas (3).csv.
-- As notas sao ligadas aos contratos mensais para compor a linha do tempo do contrato.

alter table public.lancamentos
  add column if not exists contrato_id bigint references public.contratos_mensais(id),
  add column if not exists competencia text,
  add column if not exists valor_previsto numeric(14, 2);

drop index if exists public.lancamentos_contrato_competencia_unique;

create index if not exists idx_lancamentos_contrato_competencia
  on public.lancamentos (contrato_id, competencia)
  where contrato_id is not null and competencia is not null;

with tmp_lancamentos_historicos (
  fornecedor_nome,
  contrato_usado,
  contrato_original,
  contrato_novo,
  filial_codigo,
  centro_custo_usado,
  descricao_servico,
  servico_protheus,
  numero_nota,
  valor,
  data_vencimento,
  data_envio,
  competencia,
  numero_medicao,
  numero_pedido,
  solicitacao_fluig,
  status_sharepoint,
  observacao,
  observacao_protheus,
  recebimento,
  recibo_provisorio
) as (
