resolvidos as (
  select
    tmp.*,
    f.id as fornecedor_id,
    fl.id as filial_id,
    contrato.id as contrato_id,
    contrato.cnpj_usado,
    contrato.centro_custo_usado as contrato_centro_custo,
    contrato.descricao_servico as contrato_descricao_servico,
    contrato.produto_protheus as contrato_produto_protheus,
    contrato.servico_protheus as contrato_servico_protheus,
    contrato.valor_base_previsto,
    case
      when lower(coalesce(tmp.status_sharepoint, '')) like '%conclu%' then 'concluida'
      when lower(coalesce(tmp.status_sharepoint, '')) like '%conting%' then 'contingencia'
      when lower(coalesce(tmp.status_sharepoint, '')) like '%analise%'
        or lower(coalesce(tmp.status_sharepoint, '')) like '%análise%'
        or lower(coalesce(tmp.status_sharepoint, '')) like '%nota recebida%' then 'em_analise'
      else 'pendente'
    end as etapa_calculada,
    case
      when lower(coalesce(tmp.status_sharepoint, '')) like '%conclu%' then 'Concluída'
      when lower(coalesce(tmp.status_sharepoint, '')) like '%conting%' then 'Aguardando Contingência Gerente'
      when lower(coalesce(tmp.status_sharepoint, '')) like '%analise%'
        or lower(coalesce(tmp.status_sharepoint, '')) like '%análise%'
        or lower(coalesce(tmp.status_sharepoint, '')) like '%nota recebida%' then 'Aguardando Aprovação Fluig'
      when lower(coalesce(tmp.status_sharepoint, '')) like '%aguardando%' then 'Pendente Fatura'
      else 'Pendente Nota'
    end as status_calculado
  from tmp_lancamentos_historicos tmp
  join public.fornecedores f
    on f.nome_empresa = tmp.fornecedor_nome
  left join public.filiais fl
    on fl.codigo = tmp.filial_codigo
  left join lateral (
    select cm.*
    from public.contratos_mensais cm
    where cm.fornecedor_id = f.id
      and cm.contrato_usado in (
        tmp.contrato_usado,
        nullif(tmp.contrato_original, ''),
        nullif(tmp.contrato_novo, '')
      )
    order by
      case when cm.centro_custo_usado = tmp.centro_custo_usado then 0 else 1 end,
      case when cm.contrato_usado = tmp.contrato_usado then 0 else 1 end,
      cm.id desc
    limit 1
  ) contrato on true
)
insert into public.lancamentos (
  contrato_id,
  competencia,
  filial_id,
  fornecedor_id,
  cnpj_usado,
  contrato_usado,
  centro_custo_usado,
  numero_nota,
  serie,
  valor,
  valor_previsto,
  data_envio,
  data_vencimento,
  descricao_servico,
  servico_protheus,
  numero_medicao,
  numero_pedido,
  solicitacao_fluig,
  observacao,
  etapa,
  status_pagamento,
  arquivo_nota,
  arquivo_boleto,
  repetir_por
)
select
  r.contrato_id,
  r.competencia,
  r.filial_id,
  r.fornecedor_id,
  r.cnpj_usado,
  r.contrato_usado,
  coalesce(nullif(r.centro_custo_usado, ''), r.contrato_centro_custo),
  r.numero_nota,
  'U',
  r.valor,
  coalesce(r.valor_base_previsto, r.valor),
  r.data_envio,
  r.data_vencimento,
  coalesce(nullif(r.descricao_servico, ''), r.contrato_descricao_servico),
  coalesce(nullif(r.servico_protheus, ''), r.contrato_produto_protheus, r.contrato_servico_protheus),
  nullif(r.numero_medicao, ''),
  nullif(r.numero_pedido, ''),
  nullif(r.solicitacao_fluig, ''),
  concat_ws(' | ',
    nullif(r.observacao, ''),
    nullif(r.observacao_protheus, ''),
    case when nullif(r.recebimento, '') is not null then 'Recebimento: ' || r.recebimento end,
    case when nullif(r.recibo_provisorio, '') is not null then 'RPS: ' || r.recibo_provisorio end,
    'Carga historica SharePoint'
  ),
  r.etapa_calculada,
  r.status_calculado,
  null,
  null,
  1
from resolvidos r
where r.contrato_id is not null
  and not exists (
    select 1
    from public.lancamentos l
    where l.fornecedor_id = r.fornecedor_id
      and l.numero_nota = r.numero_nota
      and l.data_vencimento = r.data_vencimento
      and abs(coalesce(l.valor, 0) - r.valor) < 0.01
  );
